    \"\"\"A cover record and its canonical archive.org location.\"\"\"

    def __init__(self, data):
        self.__dict__.update(dict(data))

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        value = f\"{int(cover_id):010d}\"
        return value[:4], value[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        size = (size or '').lower()
        if size not in SIZES:
            raise ValueError(\"size must be one of '', 's', 'm', or 'l'\")
        protocol = protocol.rstrip(':/')
        if protocol not in ('http', 'https'):
            raise ValueError(\"protocol must be 'http' or 'https'\")
        ext = ext.lstrip('.')
        prefix = f'{size}_' if size else ''
        item = f'{prefix}covers_{item_id}'
        archive = f'{prefix}covers_{item_id}_{batch_id}.zip'
        suffix = f'-{size.upper()}' if size else ''
        filename = f'{int(cover_id):010d}{suffix}.{ext}'
        return f'{protocol}://archive.org/download/{item}/{archive}/{filename}'

