        return self.get_cover_url(self.id, size, ext, protocol)


class CoverDB:
    \"\"\"Database operations for archive batches.\"\"\"

    def __init__(self):
        self.db = db.getdb()

    @staticmethod
    def _get_batch_end_id(start_id):
        return ((int(start_id) // 10_000) + 1) * 10_000 - 1

    def update_completed_batch(self, item_id, batch_id, ext='jpg'):
        item_id, batch_id = int(item_id), int(batch_id)
        start_id = item_id * 1_000_000 + batch_id * 10_000
        end_id = self._get_batch_end_id(start_id)
        # Store the canonical archive.org URL in every filename column so reads
        # no longer depend on local tar offsets or staging files.
        updates = []
        for cover_id in range(start_id, end_id + 1):
            updates.append((cover_id, [Cover.get_cover_url(cover_id, s, ext) for s in SIZES]))
        for cover_id, urls in updates:
            self.db.query(
                \"UPDATE cover SET archived=true, uploaded=true, filename="'$filename, "
                "filename_s=$filename_s, filename_m=$filename_m, filename_l=$filename_l "
                "WHERE id=$id AND failed=false",
                vars={'"'id': cover_id, 'filename': urls[0], 'filename_s': urls[1],
                      'filename_m': urls[2], 'filename_l': urls[3]},
            )

    def pending(self, limit=10000):
        return self.db.select('cover', where='archived="'$f AND failed=$f'"',
                              order='id', vars={'f': False}, limit=limit)


class ZipManager:
    \"\"\"Write uncompressed zip files, avoiding duplicate members.\"\"\"

    def __init__(self):
        self.zipfiles = {}
        self.added = {}

    def get_zipfile(self, name):
        match = re.match(r'"'^('"\\d{10})(?:-([SML]))?\\.(\\w+)"'$'"', os.path.basename(name))
        if not match:
            raise ValueError(f'Invalid cover archive filename: {name}')
        cover_id, size, _ext = match.groups()
        item_id, batch_id = Cover.id_to_item_and_batch_id(int(cover_id))
        size = (size or '').lower()
        path = Batch.get_abspath(item_id, batch_id, size)
        os.makedirs(os.path.dirname(path), exist_ok=True)
        if path not in self.zipfiles:
            self.zipfiles[path] = zipfile.ZipFile(path, 'a', compression=zipfile.ZIP_STORED)
            self.added[path] = set(self.zipfiles[path].namelist())
        return self.zipfiles[path]

