            info.compress_type = zipfile.ZIP_STORED
            with open(filepath, 'rb') as src:
                archive.writestr(info, src.read())
            self.added[path].add(name)
        return os.path.relpath(path, config.data_root)

    def close(self):
        for archive in self.zipfiles.values():
            archive.close()
        self.zipfiles.clear()


